### 3. 应用程序使用示例

```c
#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include "my_driver.h"

int main(void)
{
    int fd = open("/dev/mydev", O_RDWR);
    if (fd < 0)
    {
        perror("open failed");
        return -1;
    }

    /* 1. 无参数命令 */
    printf("=== Reset device ===\n");
    ioctl(fd, MYDEVIOC_RESET, 0);

    /* 2. 获取设备信息（驱动 → 应用） */
    printf("\n=== Get device info ===\n");
    struct mydev_info_s info;
    ioctl(fd, MYDEVIOC_GETINFO, &info);
    printf("  version:     0x%08x\n", info.version);
    printf("  buffer_size: %u\n", info.buffer_size);
    printf("  name:        %s\n", info.name);

    /* 3. 设置配置（应用 → 驱动） */
    printf("\n=== Set config ===\n");
    struct mydev_config_s cfg;
    cfg.mode     = 1;
    cfg.baudrate = 9600;
    ioctl(fd, MYDEVIOC_SETCONFIG, &cfg);

    /* 4. 读写寄存器（双向） */
    printf("\n=== RW register ===\n");
    struct mydev_reg_s reg;
    reg.reg_addr  = 0x40001000;
    reg.reg_value = 0;
    ioctl(fd, MYDEVIOC_RWREG, &reg);
    printf("  addr=0x%08x, value=0x%08x\n",
           reg.reg_addr, reg.reg_value);

    close(fd);
    return 0;
}
