678	
679	static int btn_poll(FAR struct file *filep, FAR struct pollfd *fds,
680	                    bool setup)
681	{
682	  FAR struct inode *inode;
683	  FAR struct btn_upperhalf_s *priv;
684	  FAR struct btn_open_s *opriv;
685	  irqstate_t flags;
686	  int ret = OK;
687	  int i;
688	
689	  DEBUGASSERT(filep->f_priv);
690	  opriv = filep->f_priv;
691	  inode = filep->f_inode;
692	  DEBUGASSERT(inode->i_private);
693	  priv  = inode->i_private;
694	
695	  /* Get exclusive access to the driver structure */
696	
697	  flags = spin_lock_irqsave_nopreempt(&priv->lock);
698	
699	  /* Are we setting up the poll?  Or tearing it down? */
700	
701	  if (setup)
702	    {
703	      /* This is a request to set up the poll.  Find an available
704	       * slot for the poll structure reference
705	       */
706	
707	      for (i = 0; i < CONFIG_INPUT_BUTTONS_NPOLLWAITERS; i++)
708	        {
709	          /* Find an available slot */
710	
711	          if (!opriv->bo_fds[i])
712	            {
713	              /* Bind the poll structure and this slot */
714	
715	              opriv->bo_fds[i] = fds;
716	              fds->priv = &opriv->bo_fds[i];
717	
718	              /* Report if the event is pending */
719	
720	              if (opriv->bo_pending)
721	                {
722	                  poll_notify(&fds, 1, POLLIN);
723	                }
724	
725	              break;
726	            }
727	        }
728	
729	      if (i >= CONFIG_INPUT_BUTTONS_NPOLLWAITERS)
730	        {
731	          spin_unlock_irqrestore_nopreempt(&priv->lock, flags);
732	          ierr("ERROR: Too many poll waiters\n");
733	          fds->priv = NULL;
734	          ret       = -EBUSY;
735	          goto errout;
736	        }
737	    }
738	  else if (fds->priv)
739	    {
740	      /* This is a request to tear down the poll. */
741	
742	      FAR struct pollfd **slot = (FAR struct pollfd **)fds->priv;
743	
744	#ifdef CONFIG_DEBUG_FEATURES

740	      /* This is a request to tear down the poll. */
741	
742	      FAR struct pollfd **slot = (FAR struct pollfd **)fds->priv;
743	
744	#ifdef CONFIG_DEBUG_FEATURES
745	      if (!slot)
746	        {
747	          spin_unlock_irqrestore_nopreempt(&priv->lock, flags);
748	          ierr("ERROR: Poll slot not found\n");
749	          ret = -EIO;
750	          goto errout;
751	        }
752	#endif
753	
754	      /* Remove all memory of the poll setup */
755	
756	      *slot     = NULL;
757	      fds->priv = NULL;
758	    }
759	
760	  spin_unlock_irqrestore_nopreempt(&priv->lock, flags);
761	
762	  btn_enable(priv);
763	
764	errout:
765	  return ret;
766	}
