158	
159	static void btn_enable(FAR struct btn_upperhalf_s *priv)
160	{
161	  FAR const struct btn_lowerhalf_s *lower;
162	  FAR struct btn_open_s *opriv;
163	  btn_buttonset_t press;
164	  btn_buttonset_t release;
165	  irqstate_t flags;
166	
167	  DEBUGASSERT(priv && priv->bu_lower);
168	  lower = priv->bu_lower;
169	  DEBUGASSERT(lower->bl_enable);
170	
171	  /* This routine is called both task level and interrupt level, so
172	   * interrupts must be disabled.
173	   */
174	
175	  flags = spin_lock_irqsave(&priv->lock);
176	
177	  /* Visit each opened reference to the device */
178	
179	  press   = 0;
180	  release = 0;
181	
182	  for (opriv = priv->bu_open; opriv; opriv = opriv->bo_flink)
183	    {
184	      /* OR in the poll event buttons */
185	
186	      press   |= opriv->bo_pollevents.bp_press;
187	      release |= opriv->bo_pollevents.bp_release;
188	
189	      /* OR in the signal events */
190	
191	      press   |= opriv->bo_notify.bn_press;
192	      release |= opriv->bo_notify.bn_release;
193	    }
194	
195	  spin_unlock_irqrestore(&priv->lock, flags);
196	
197	  nxmutex_lock(&priv->mutex);
198	
199	  /* Enable/disable button interrupts */
200	
201	  if (press != 0 || release != 0)
202	    {
203	      /* Update last sampled button states when enabling interrupts for
204	       * the first time.
205	       */
206	
207	      if (!priv->bu_enabled)
208	        {
209	          priv->bu_enabled = true;
210	          priv->bu_sample = lower->bl_buttons(lower);
211	        }
212	
213	      /* Enable interrupts with the new button set */
214	
215	      lower->bl_enable(lower, press, release,
216	                       (btn_handler_t)btn_interrupt, priv);
217	    }
218	  else
219	    {
220	      priv->bu_enabled = false;
221	
222	      /* Disable further interrupts */
223	
224	      lower->bl_enable(lower, 0, 0, NULL, NULL);
225	    }
226	
227	    nxmutex_unlock(&priv->mutex);
228	}
