253	/****************************************************************************
254	 * Name: poll_notify
255	 *
256	 * Description:
257	 *   Notify the poll, this function should be called by drivers to notify
258	 *   the caller the poll is ready.
259	 *
260	 * Input Parameters:
261	 *   afds     - The fds array
262	 *   nfds     - Number of fds array
263	 *   eventset - List of events to check for activity
264	 *
265	 * Returned Value:
266	 *   None
267	 *
268	 ****************************************************************************/
269	
270	void poll_notify(FAR struct pollfd **afds, int nfds, pollevent_t eventset)
271	{
272	  int i;
273	  FAR struct pollfd *fds;
274	
275	  DEBUGASSERT(afds != NULL && nfds >= 1);
276	
277	  for (i = 0; i < nfds && eventset; i++)
278	    {
279	      fds = afds[i];
280	      if (fds != NULL)
281	        {
282	          /* The error event must be set in fds->revents */
283	
284	          fds->revents |= eventset & (fds->events | POLLERR | POLLHUP);
285	          if ((fds->revents & (POLLERR | POLLHUP)) != 0)
286	            {
287	              /* Error or Hung up, clear POLLOUT event */
288	
289	              fds->revents &= ~POLLOUT;
290	            }
291	
292	          if ((fds->revents != 0 || (fds->events & POLLALWAYS) != 0) &&
293	              fds->cb != NULL)
294	            {
295	              finfo("Report events: %08" PRIx32 "\n", fds->revents);
296	              fds->cb(fds);
297	            }
298	        }
299	    }

