302	/****************************************************************************
303	 * Name: file_poll
304	 *
305	 * Description:
306	 *   Low-level poll operation based on struct file.  This is used to
307	 *   support detached file.
308	 *
309	 * Input Parameters:
310	 *   file     File structure instance
311	 *   fds   - The structure describing the events to be monitored, OR NULL if
312	 *           this is a request to stop monitoring events.
313	 *   setup - true: Setup up the poll; false: Teardown the poll
314	 *
315	 * Returned Value:
316	 *  0: Success; Negated errno on failure
317	 *
318	 ****************************************************************************/
319	
320	int file_poll(FAR struct file *filep, FAR struct pollfd *fds, bool setup)
321	{
322	  FAR struct inode *inode;
323	  int ret = -ENOSYS;
324	
325	  DEBUGASSERT(filep != NULL);
326	  inode = filep->f_inode;
327	
328	  if (inode != NULL)
329	    {
330	      /* Is a driver registered? Does it support the poll method?
331	       * If not, return -ENOSYS
332	       */
333	
334	      if ((INODE_IS_DRIVER(inode) || INODE_IS_MQUEUE(inode) ||
335	          INODE_IS_SOCKET(inode) || INODE_IS_PIPE(inode)) &&
336	          inode->u.i_ops != NULL && inode->u.i_ops->poll != NULL)
337	        {
338	          /* Yes, it does... Setup the poll */
339	
340	          ret = inode->u.i_ops->poll(filep, fds, setup);
341	          if (ret < 0)
342	            {
343	              ferr("poll failed:%p, setup:%d, ret:%d\n",
344	                   inode->u.i_ops->poll, setup, ret);
345	            }
346	        }
347	#ifndef CONFIG_DISABLE_MOUNTPOINT
348	      else if (INODE_IS_MOUNTPT(inode) && inode->u.i_mops != NULL &&
349	               inode->u.i_mops->poll != NULL)
350	        {
351	          ret = inode->u.i_mops->poll(filep, fds, setup);
352	          if (ret < 0)
353	            {
354	              ferr("poll failed:%p, setup:%d, ret:%d\n",
355	                   inode->u.i_ops->poll, setup, ret);
356	            }
357	        }
358	#endif
359	
360	      /* Regular files (and block devices) are always readable and
361	       * writable. Open Group: "Regular files shall always poll TRUE for
362	       * reading and writing."
363	       */
364	
365	      else if (INODE_IS_MOUNTPT(inode) || INODE_IS_BLOCK(inode) ||
366	               INODE_IS_MTD(inode))
367	        {
368	          if (setup)
369	            {
370	              poll_notify(&fds, 1, POLLIN | POLLOUT);
371	            }
372	
373	          ret = OK;
374	        }
375	    }
376	  else
377	    {
378	      poll_notify(&fds, 1, POLLERR | POLLHUP);
379	      ret = OK;
380	    }
381	
382	  return ret;
383	}
