385	/****************************************************************************
386	 * Name: poll
387	 *
388	 * Description:
389	 *   poll() waits for one of a set of file descriptors to become ready to
390	 *   perform I/O.  If none of the events requested (and no error) has
391	 *   occurred for any of  the  file  descriptors,  then  poll() blocks until
392	 *   one of the events occurs.
393	 *
394	 * Input Parameters:
395	 *   fds  - List of structures describing file descriptors to be monitored
396	 *   nfds - The number of entries in the list
397	 *   timeout - Specifies an upper limit on the time for which poll() will
398	 *     block in milliseconds.  A negative value of timeout means an infinite
399	 *     timeout.
400	 *
401	 * Returned Value:
402	 *   On success, the number of structures that have non-zero revents fields.
403	 *   A value of 0 indicates that the call timed out and no file descriptors
404	 *   were ready.  On error, -1 is returned, and errno is set appropriately:
405	 *
406	 *   EBADF  - An invalid file descriptor was given in one of the sets.
407	 *   EFAULT - The fds address is invalid
408	 *   EINTR  - A signal occurred before any requested event.
409	 *   EINVAL - The nfds value exceeds a system limit.
410	 *   ENOMEM - There was no space to allocate internal data structures.
411	 *   ENOSYS - One or more of the drivers supporting the file descriptor
412	 *     does not support the poll method.
413	 *
414	 ****************************************************************************/
415	
416	int poll(FAR struct pollfd *fds, nfds_t nfds, int timeout)
417	{
418	  FAR struct pollfd *kfds;
419	  FAR sem_t *sem;
420	  int count = 0;
421	  int ret = OK;
422	#if !defined(CONFIG_BUILD_KERNEL) && !defined(CONFIG_BUILD_PROTECTED)
423	  sem_t local_sem;
424	  sem = &local_sem;
425	#endif
426	
427	  DEBUGASSERT(nfds == 0 || fds != NULL);
428	
429	  /* poll() is a cancellation point */
430	
431	  enter_cancellation_point();
432	
433	#if defined(CONFIG_BUILD_KERNEL) || defined(CONFIG_BUILD_PROTECTED)
434	  /* Allocate kernel memory for the fds */
435	
436	  kfds = fs_heap_malloc(nfds * sizeof(struct pollfd) + sizeof(sem_t));
437	  if (!kfds)
438	    {
439	      /* Out of memory */
440	
441	      ret = -ENOMEM;
442	      goto out_with_cancelpt;
443	    }
444	
445	  /* Copy the user fds to neutral kernel memory */
446	
447	  memcpy(kfds, fds, nfds * sizeof(struct pollfd));
448	  sem = (FAR sem_t *)((uintptr_t)kfds + nfds * sizeof(struct pollfd));
449	#else

449	#else
450	  /* Can use the user fds directly */
451	
452	  kfds = fds;
453	#endif
454	
455	  /* Set up the poll structure */
456	
457	  nxsem_init(sem, 0, 0);
458	
459	  /* If there are already events available in poll_setup,
460	   * we return immediately
461	   */
462	
463	  count = poll_setup(kfds, nfds, sem);
464	  if (count == 0)
465	    {
466	      struct pollfd_s fdsinfo;
467	
468	      /* Push a cancellation point onto the stack.  This will be called if
469	       * the thread is canceled.
470	       */
471	
472	      fdsinfo.fds = kfds;
473	      fdsinfo.nfds = nfds;
474	      tls_cleanup_push(tls_get_info(), poll_cleanup, &fdsinfo);
475	
476	      if (timeout > 0)
477	        {
478	          /* "Implementations may place limitations on the granularity of
479	           * timeout intervals. If the requested timeout interval requires
480	           * a finer granularity than the implementation supports, the
481	           * actual timeout interval will be rounded up to the next
482	           * supported value." -- opengroup.org
483	           *
484	           * Round timeout up to next full tick.
485	           */
486	
487	          /* Either wait for either a poll event(s), for a signal to occur,
488	           * or for the specified timeout to elapse with no event.
489	           *
490	           * NOTE: If a poll event is pending (i.e., the semaphore has
491	           * already been incremented), nxsem_tickwait() will not wait, but
492	           * will return immediately.
493	           */
494	
495	          ret = nxsem_tickwait(sem, MSEC2TICK((clock_t)timeout));
496	          if (ret < 0)
497	            {
498	              if (ret == -ETIMEDOUT)
499	                {
500	                  /* Return zero (OK) in the event of a timeout */
501	
502	                  ret = OK;
503	                }
504	
505	              /* EINTR is the only other error expected in normal operation */
506	            }
507	        }
508	      else if (timeout < 0)
509	        {
510	          /* Wait for the poll event or signal with no timeout */
511	
512	          ret = nxsem_wait(sem);
513	        }
514	
515	      /* Teardown the poll operation and get the count of events.  Zero will
516	       * be returned in the case of a timeout.
517	       *
518	       * Preserve ret, if negative, since it holds the result of the wait.
519	       */
520	
521	      poll_teardown(kfds, nfds, &count);
522	
523	      /* Pop the cancellation point */
524	
525	      tls_cleanup_pop(tls_get_info(), 0);
526	    }
527	
528	  nxsem_destroy(sem);
529	
530	#if defined(CONFIG_BUILD_KERNEL) || defined(CONFIG_BUILD_PROTECTED)
531	  /* Copy the events back to user */
532	
533	  if (ret == OK)
534	    {
535	      int i;
536	      for (i = 0; i < nfds; i++)
537	        {
538	          fds[i].revents = kfds[i].revents;
539	        }
540	    }
541	
542	  /* Free the temporary buffer */
543	
544	  fs_heap_free(kfds);
545	
546	out_with_cancelpt:
547	#endif
548

548	
549	  leave_cancellation_point();
550	
551	  if (ret < 0)
552	    {
553	      set_errno(-ret);
554	      return ERROR;
555	    }
556	  else
557	    {
558	      return count;
559	    }
560	}
